solution:
def solve(x, y):
    if len(x) < 2:
        return None
    mx, my = sum(x) / len(x), sum(y) / len(y)
    denominator = sum((v - mx) ** 2 for v in x)
    if denominator == 0:
        return None
    slope = sum((a - mx) * (b - my) for a, b in zip(x, y)) / denominator
    return [my - slope * mx, slope]

