solution:
def solve(values, lag):
    if len(values) <= lag:
        return None
    mean = sum(values) / len(values)
    d = [v - mean for v in values]
    denominator = sum(v * v for v in d)
    if denominator == 0:
        return None
    return sum(d[i] * d[i-lag] for i in range(lag, len(d))) / denominator

