def solve(probabilities, outcomes, bins):
    groups = [[] for _ in range(bins)]
    for p, y in zip(probabilities, outcomes):
        groups[min(int(p * bins), bins - 1)].append((p, y))
    return {"brier": sum((p-y)**2 for p,y in zip(probabilities,outcomes)) / len(probabilities) if probabilities else None,
            "bins": [[len(g), sum(p for p,y in g)/len(g), sum(y for p,y in g)/len(g)] if g else [0,None,None] for g in groups]}
